def cmp_semver(a: str, b: str) -> int:
    def parse(v: str):
        # Strip build metadata (everything after '+')
        v = v.split('+', 1)[0]
        # Split off pre-release
        if '-' in v:
            core_part, prerelease = v.rsplit('-', 1)
        else:
            core_part, prerelease = v, None
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])
        return (major, minor, patch), prerelease

    def cmp_prerelease(pa: str | None, pb: str | None) -> int:
        # A version with no pre-release has higher precedence than one with a pre-release
        if pa is None and pb is None:
            return 0
        if pa is None:
            return 1   # b has prerelease, so a > b
        if pb is None:
            return -1  # a has prerelease, so a < b

        ids_a = pa.split('.')
        ids_b = pb.split('.')

        for ia, ib in zip(ids_a, ids_b):
            # Determine type: numeric or alphanumeric
            a_num = ia.isdigit()
            b_num = ib.isdigit()

            if a_num and b_num:
                na, nb = int(ia), int(ib)
                if na < nb:
                    return -1
                elif na > nb:
                    return 1
                else:
                    continue
            elif a_num and not b_num:
                # Numeric identifiers sort before alphanumeric ones
                return -1
            elif not a_num and b_num:
                return 1
            else:
                # Both alphanumeric, compare as strings (ASCII)
                if ia < ib:
                    return -1
                elif ia > ib:
                    return 1
                else:
                    continue

        # All preceding identifiers are equal; the longer list has higher precedence
        if len(ids_a) < len(ids_b):
            return -1
        elif len(ids_a) > len(ids_b):
            return 1
        else:
            return 0

    (ma, mi, pa), pre_a = parse(a)
    (mb, mi_b, pb), pre_b = parse(b)

    # Compare major, minor, patch numerically
    if ma != mb:
        return -1 if ma < mb else 1
    if mi != mi_b:
        return -1 if mi < mi_b else 1
    if pa != pb:
        return -1 if pa < pb else 1

    # Compare pre-release
    return cmp_prerelease(pre_a, pre_b)
