import re


def parse_duration(s):
    if not isinstance(s, str) or len(s) == 0:
        raise ValueError("Invalid duration")

    sign = 1
    rest = s
    if rest.startswith('-'):
        sign = -1
        rest = rest[1:]
    elif rest.startswith('+'):
        rest = rest[1:]

    # Must start with 'P'
    if not rest.startswith('P'):
        raise ValueError("Invalid duration: must start with P")
    rest = rest[1:]

    if len(rest) == 0:
        raise ValueError("Invalid duration: no fields present")

    total_seconds = 0.0
    has_any_field = False

    # Parse date part (before T) and time part (after T)
    t_index = rest.find('T')
    if t_index != -1:
        date_part = rest[:t_index]
        time_part = rest[t_index + 1:]
    else:
        date_part = rest
        time_part = None

    # Parse date part: nY, nM (months), nD
    # We need to parse fields in order: Y, M, D
    i = 0
    years = 0.0
    months = 0.0
    days = 0.0

    while i < len(date_part):
        if date_part[i].isdigit() or date_part[i] == '.':
            # Parse number
            j = i
            while j < len(date_part) and (date_part[j].isdigit() or date_part[j] == '.'):
                j += 1
            num_str = date_part[i:j]
            try:
                val = float(num_str)
            except ValueError:
                raise ValueError("Invalid duration: bad number")
            i = j
            if i >= len(date_part):
                raise ValueError("Invalid duration: missing unit after number in date part")
            unit = date_part[i]
            i += 1
            if unit == 'Y':
                years = val
                has_any_field = True
            elif unit == 'M':
                months = val
                has_any_field = True
            elif unit == 'D':
                days = val
                has_any_field = True
            else:
                raise ValueError("Invalid duration: unexpected unit in date part")
        else:
            raise ValueError("Invalid duration: unexpected character in date part")

    # Parse time part if present
    hours = 0.0
    minutes = 0.0
    seconds = 0.0

    if time_part is not None:
        if len(time_part) == 0:
            raise ValueError("Invalid duration: T with no time fields")
        i = 0
        while i < len(time_part):
            if time_part[i].isdigit() or time_part[i] == '.':
                j = i
                while j < len(time_part) and (time_part[j].isdigit() or time_part[j] == '.'):
                    j += 1
                num_str = time_part[i:j]
                try:
                    val = float(num_str)
                except ValueError:
                    raise ValueError("Invalid duration: bad number")
                i = j
                if i >= len(time_part):
                    raise ValueError("Invalid duration: missing unit after number in time part")
                unit = time_part[i]
                i += 1
                if unit == 'H':
                    hours = val
                    has_any_field = True
                elif unit == 'M':
                    minutes = val
                    has_any_field = True
                elif unit == 'S':
                    seconds = val
                    has_any_field = True
                else:
                    raise ValueError("Invalid duration: unexpected unit in time part")
            else:
                raise ValueError("Invalid duration: unexpected character in time part")

    if not has_any_field:
        raise ValueError("Invalid duration: no fields present")

    total_seconds = (years * 365 + months * 30 + days) * 86400.0 + hours * 3600.0 + minutes * 60.0 + seconds
    return sign * total_seconds
