import re
from datetime import datetime, timedelta


def _parse_field(field_str, min_val, max_val, name):
    """Parse a single cron field and return a set of valid values."""
    if not field_str:
        raise ValueError(f"Empty {name} field")

    values = set()
    parts = field_str.split(',')

    for part in parts:
        part = part.strip()
        if not part:
            raise ValueError(f"Empty component in {name} field")

        # Check for step value
        if '/' in part:
            base, step_str = part.split('/', 1)
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError(f"Invalid step value '{step_str}' in {name} field")
            if step <= 0:
                raise ValueError(f"Step must be positive in {name} field")
        else:
            base = part
            step = None

        # Parse the base range
        if base == '*':
            start, end = min_val, max_val
        elif '-' in base:
            a_str, b_str = base.split('-', 1)
            try:
                a = int(a_str)
                b = int(b_str)
            except ValueError:
                raise ValueError(f"Invalid range '{base}' in {name} field")
            if a < min_val or a > max_val or b < min_val or b > max_val:
                raise ValueError(f"Range out of bounds in {name} field: {a}-{b}")
            if a > b:
                raise ValueError(f"Invalid range '{base}' in {name} field")
            start, end = a, b
        else:
            try:
                val = int(base)
            except ValueError:
                raise ValueError(f"Invalid value '{base}' in {name} field")
            if val < min_val or val > max_val:
                raise ValueError(f"Value out of bounds in {name} field: {val}")
            start, end = val, val

        # Generate values with step
        if step is None:
            for v in range(start, end + 1):
                values.add(v)
        else:
            for v in range(start, end + 1, step):
                values.add(v)

    return values


def _is_restricted(field_str):
    """Check if a field is restricted (not just '*')."""
    # A field is restricted if it's not exactly '*'
    # But we need to be careful: '*/1' is equivalent to '*', but the spec says "neither is *"
    # The standard cron rule checks if the field string is literally '*' or contains restrictions.
    # Per POSIX and common implementations, a field is considered "restricted" if it's not '*'.
    return field_str != '*'


def next_fire(expr, after):
    """Return the next datetime strictly after `after` at which the cron expression fires."""
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Cron expression must have exactly 5 fields, got {len(fields)}")

    minute_str, hour_str, dom_str, month_str, dow_str = fields

    # Parse each field into sets of valid values
    minutes = _parse_field(minute_str, 0, 59, "minute")
    hours = _parse_field(hour_str, 0, 23, "hour")
    days_of_month = _parse_field(dom_str, 1, 31, "day-of-month")
    months = _parse_field(month_str, 1, 12, "month")
    days_of_week = _parse_field(dow_str, 0, 6, "day-of-week")

    # Determine if dom and dow are restricted
    dom_restricted = _is_restricted(dom_str)
    dow_restricted = _is_restricted(dow_str)

    # Start from the next minute after `after`
    dt = (after + timedelta(minutes=1)).replace(second=0, microsecond=0)

    # We'll iterate forward, checking each candidate datetime
    # To be efficient, we can skip ahead when possible

    max_iterations = 366 * 24 * 60 * 5  # ~5 years worth of minutes as a safety limit
    for _ in range(max_iterations):
        month = dt.month
        day = dt.day
        hour = dt.hour
        minute = dt.minute

        # Check if this datetime matches the cron expression
        if month not in months:
            # Skip to next month
            if month == 12:
                dt = dt.replace(year=dt.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                dt = dt.replace(month=month + 1, day=1, hour=0, minute=0)
            continue

        # Check day matching
        dom_match = day in days_of_month
        dow_match = (dt.weekday() + 1) % 7 in days_of_week  # Convert Python weekday (Mon=0) to cron (Sun=0)

        if dom_restricted and dow_restricted:
            day_ok = dom_match or dow_match
        elif dom_restricted:
            day_ok = dom_match
        elif dow_restricted:
            day_ok = dow_match
        else:
            day_ok = True

        if not day_ok:
            # Skip to next day
            dt = (dt + timedelta(days=1)).replace(hour=0, minute=0)
            continue

        if hour not in hours:
            # Skip to next hour
            if hour == 23:
                dt = (dt + timedelta(days=1)).replace(hour=0, minute=0)
            else:
                dt = dt.replace(hour=hour + 1, minute=0)
            continue

        if minute not in minutes:
            # Skip to next minute
            if minute == 59:
                if hour == 23:
                    dt = (dt + timedelta(days=1)).replace(hour=0, minute=0)
                else:
                    dt = dt.replace(hour=hour + 1, minute=0)
            else:
                dt = dt.replace(minute=minute + 1)
            continue

        # All fields match
        return dt

    raise ValueError("No matching datetime found within search limit")
