def wildcard_match(pattern: str, s: str) -> bool:
    m = len(s)
    n = len(pattern)

    # dp[i][j] means whether pattern[:i] matches s[:j]
    # We can optimize space to O(n) but let's do O(m*n) time with O(min(m,n)) or just O(n) space.
    # Actually, the requirement is time proportional to len(pattern)*len(s), so O(m*n) time is fine.

    # Use 1D DP: dp[j] = whether pattern[:i] matches s[:j]
    # Initialize for i=0 (empty pattern): only j=0 is True
    dp = [False] * (m + 1)
    dp[0] = True

    for i in range(1, n + 1):
        p_char = pattern[i - 1]
        new_dp = [False] * (m + 1)

        if p_char == '*':
            # '*' can match empty: new_dp[j] |= dp[j]
            # '*' can match one or more chars: new_dp[j] |= new_dp[j-1] (if j > 0)
            for j in range(m + 1):
                if dp[j]:
                    new_dp[j] = True
                if j > 0 and new_dp[j - 1]:
                    new_dp[j] = True
        elif p_char == '?':
            # '?' matches exactly one character: new_dp[j] |= dp[j-1] (if j > 0)
            for j in range(1, m + 1):
                if dp[j - 1]:
                    new_dp[j] = True
        else:
            # Literal character match
            for j in range(1, m + 1):
                if dp[j - 1] and s[j - 1] == p_char:
                    new_dp[j] = True

        dp = new_dp

    return dp[m]
