class RollbackDSU:
    def __init__(self, n):
        self.n = n
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []  # stack of (child_root, parent_root, size_of_parent_before)

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        # Union by size: attach smaller tree to larger tree
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        # Now size[ra] >= size[rb], so we attach rb under ra
        self.history.append((rb, ra, self.size[ra]))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        return True

    def snapshot(self):
        return len(self.history)

    def rollback(self, token):
        while len(self.history) > token:
            child_root, parent_root, size_of_parent_before = self.history.pop()
            self.parent[child_root] = child_root
            self.size[parent_root] = size_of_parent_before

    def components(self):
        return sum(1 for i in range(self.n) if self.find(i) == i)
