class WildcardTrie:
    def __init__(self):
        self.root = {}
        self.word_counts = {}  # track how many times each word is added

    def add(self, word):
        node = self.root
        for ch in word:
            if ch not in node:
                node[ch] = {}
            node = node[ch]
        # Mark end of word with a count
        if '#' not in node:
            node['#'] = 0
        node['#'] += 1
        self.word_counts[word] = self.word_counts.get(word, 0) + 1

    def remove(self, word):
        if word not in self.word_counts or self.word_counts[word] == 0:
            return False
        # Decrement count
        node = self.root
        for ch in word:
            if ch not in node:
                return False
            node = node[ch]
        if '#' not in node or node['#'] <= 0:
            return False
        node['#'] -= 1
        self.word_counts[word] -= 1

        # Optionally prune nodes that are no longer needed (but be careful)
        # For simplicity and correctness, we don't prune to avoid bugs.
        # The search will still work correctly because '#' count is 0.
        return True

    def _search_helper(self, node, pattern, idx, current_word, results):
        if idx == len(pattern):
            if '#' in node and node['#'] > 0:
                results.append(current_word)
            return

        ch = pattern[idx]
        if ch == '.':
            for key, child_node in node.items():
                if key != '#':
                    self._search_helper(child_node, pattern, idx + 1, current_word + key, results)
        else:
            if ch in node:
                self._search_helper(node[ch], pattern, idx + 1, current_word + ch, results)

    def search(self, pattern):
        results = []
        self._search_helper(self.root, pattern, 0, '', results)
        return sorted(results)
