def subtract(base, cuts):
    # Normalize: sort and merge overlapping/adjacent intervals for both base and cuts
    def normalize(intervals):
        if not intervals:
            return []
        sorted_ivs = sorted(intervals)
        merged = [list(sorted_ivs[0])]
        for s, e in sorted_ivs[1:]:
            if s <= merged[-1][1]:  # overlap or adjacent (touching)
                merged[-1][1] = max(merged[-1][1], e)
            else:
                merged.append([s, e])
        return [(s, e) for s, e in merged if s < e]

    base_norm = normalize(base)
    cuts_norm = normalize(cuts)

    result = []
    cut_idx = 0
    n_cuts = len(cuts_norm)

    for bs, be in base_norm:
        # Skip cuts that end before or at the start of this base interval
        while cut_idx < n_cuts and cuts_norm[cut_idx][1] <= bs:
            cut_idx += 1

        cur_start = bs
        i = cut_idx
        while i < n_cuts and cuts_norm[i][0] < be:
            cs, ce = cuts_norm[i]
            if ce <= cur_start:
                # This cut is entirely before our current position; skip it
                i += 1
                continue
            if cs >= be:
                break
            # There's a gap between cur_start and cs (if any)
            if cs > cur_start:
                result.append((cur_start, cs))
            # Move past this cut
            cur_start = max(cur_start, ce)
            i += 1

        # After processing all relevant cuts, check remaining part of base interval
        if cur_start < be:
            result.append((cur_start, be))

    # Merge adjacent intervals in result (they should already be non-overlapping and sorted, but merge touching ones)
    final = []
    for s, e in result:
        if not final or s > final[-1][1]:
            final.append([s, e])
        else:
            # They touch or overlap; merge
            final[-1][1] = max(final[-1][1], e)

    return [(s, e) for s, e in final if s < e]
