class TokenBucket:
    def __init__(self, capacity, refill_per_sec, clock):
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self.tokens = float(capacity)
        self.last_time = self.clock()

    def _refill(self):
        now = self.clock()
        if now < self.last_time:
            # Time never moves backwards, but guard just in case
            return
        elapsed = now - self.last_time
        if elapsed > 0 and self.refill_per_sec > 0:
            added = elapsed * self.refill_per_sec
            self.tokens = min(self.capacity, self.tokens + added)
        self.last_time = now

    def take(self, n=1):
        if n <= 0:
            return True
        if n > self.capacity:
            return False
        self._refill()
        if self.tokens >= n:
            self.tokens -= n
            return True
        return False
