import threading


def transfer_all(accounts, ops):
    n = len(accounts)
    balances = list(accounts)
    locks = [threading.Lock() for _ in range(n)]

    def get_locks(src, dst):
        """Acquire both locks in a consistent order to avoid deadlock."""
        if src < dst:
            first, second = src, dst
        else:
            first, second = dst, src
        locks[first].acquire()
        locks[second].acquire()
        return (src, dst)

    def release_locks(src, dst):
        """Release both locks in the same consistent order."""
        if src < dst:
            first, second = src, dst
        else:
            first, second = dst, src
        locks[second].release()
        locks[first].release()

    def do_transfer(src, dst, amount):
        get_locks(src, dst)
        try:
            if balances[src] >= amount:
                balances[src] -= amount
                balances[dst] += amount
        finally:
            release_locks(src, dst)

    threads = []
    for src, dst, amount in ops:
        t = threading.Thread(target=do_transfer, args=(src, dst, amount))
        threads.append(t)
        t.start()

    for t in threads:
        t.join()

    return balances
