def to_base(n: int, alphabet: str) -> str:
    if n == 0:
        return alphabet[0]

    negative = n < 0
    n = abs(n)

    base = len(alphabet)
    digits = []
    while n > 0:
        n, r = divmod(n, base)
        digits.append(alphabet[r])

    if negative:
        return '-' + ''.join(reversed(digits))
    else:
        return ''.join(reversed(digits))


def from_base(s: str, alphabet: str) -> int:
    if not s:
        raise ValueError("empty string")

    base = len(alphabet)
    char_to_val = {c: i for i, c in enumerate(alphabet)}

    negative = False
    if s[0] == '-':
        negative = True
        s = s[1:]
        if not s:
            raise ValueError("empty string after sign")

    result = 0
    for ch in s:
        if ch not in char_to_val:
            raise ValueError(f"character {ch!r} not in alphabet")
        result = result * base + char_to_val[ch]

    return -result if negative else result
