import heapq
from collections import defaultdict


def topo_lex(graph):
    # Build in-degree map and collect all nodes
    in_degree = {}
    successors = defaultdict(list)  # node -> list of nodes that depend on it (already given as graph values)

    # First pass: identify all nodes
    all_nodes = set()
    for node, deps in graph.items():
        all_nodes.add(node)
        for dep in deps:
            all_nodes.add(dep)

    # Initialize in-degree to 0 for all nodes
    for node in all_nodes:
        in_degree[node] = 0

    # Build adjacency and compute in-degrees
    # graph maps a node to the list of nodes that DEPEND ON it (its successors)
    # So if u -> [v, w], then v depends on u, meaning edge u -> v, u -> w
    # In-degree of v is incremented for each predecessor

    for node, deps in graph.items():
        for dep in deps:
            in_degree[dep] += 1

    # Initialize heap with all nodes having in-degree 0
    heap = []
    for node in all_nodes:
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        # For each successor of this node (nodes that depend on it), decrement their in-degree
        for dep in graph.get(node, []):
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                heapq.heappush(heap, dep)

    if len(result) != len(all_nodes):
        return None

    return result
