function deepEqual(a, b) {
  // SameValueZero: NaN equals NaN, +0 equals -0
  if (a === b) return true;

  // Handle NaN
  if (typeof a === 'number' && typeof b === 'number') {
    if (Number.isNaN(a) && Number.isNaN(b)) return true;
    // +0 and -0 are already handled by === above
  }

  // Different types are never equal
  if (typeof a !== typeof b) return false;
  if (Object.prototype.toString.call(a) !== Object.prototype.toString.call(b)) return false;

  // Primitives that aren't numbers: already handled by === and type check
  if (a === null || b === null) return false;
  if (typeof a !== 'object') return false;

  // Date: compare by time value
  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }

  // RegExp: compare by source and flags
  if (a instanceof RegExp && b instanceof RegExp) {
    return a.source === b.source && a.flags === b.flags;
  }

  // Map: compare by contents irrespective of insertion order
  if (a instanceof Map && b instanceof Map) {
    if (a.size !== b.size) return false;
    for (const [key, value] of a.entries()) {
      let found = false;
      for (const [bKey, bValue] of b.entries()) {
        if (deepEqual(key, bKey)) {
          if (!found && deepEqual(value, bValue)) {
            found = true;
            break;
          } else if (found) {
            // Duplicate key in a? Shouldn't happen for Map, but handle gracefully
            continue;
          }
        }
      }
      if (!found) return false;
    }
    return true;
  }

  // Set: compare by contents irrespective of insertion order
  if (a instanceof Set && b instanceof Set) {
    if (a.size !== b.size) return false;
    for (const value of a.values()) {
      let found = false;
      for (const bValue of b.values()) {
        if (deepEqual(value, bValue)) {
          found = true;
          break;
        }
      }
      if (!found) return false;
    }
    return true;
  }

  // Arrays and plain objects: compare by own enumerable keys/indices
  const aIsArray = Array.isArray(a);
  const bIsArray = Array.isArray(b);
  if (aIsArray !== bIsArray) return false;

  if (aIsArray) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) return false;
    }
    return true;
  }

  // Plain objects: compare own enumerable keys
  const aKeys = Object.keys(a);
  const bKeys = Object.keys(b);
  if (aKeys.length !== bKeys.length) return false;

  for (const key of aKeys) {
    if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
    if (!deepEqual(a[key], b[key])) return false;
  }

  return true;
}

