function pLimit(n) {
  let activeCount = 0;
  const queue = [];

  function next() {
    if (activeCount >= n || queue.length === 0) return;
    activeCount++;
    const { fn, resolve, reject } = queue.shift();
    Promise.resolve(fn())
      .then(resolve, reject)
      .finally(() => {
        activeCount--;
        next();
      });
  }

  return function (fn) {
    return new Promise((resolve, reject) => {
      queue.push({ fn, resolve, reject });
      next();
    });
  };
}

module.exports = pLimit;
