class Emitter {
  constructor() {
    this._listeners = new Map();
  }

  on(event, fn) {
    if (!this._listeners.has(event)) {
      this._listeners.set(event, []);
    }
    const listeners = this._listeners.get(event);
    listeners.push(fn);
    return () => {
      const idx = listeners.indexOf(fn);
      if (idx !== -1) {
        listeners.splice(idx, 1);
      }
    };
  }

  once(event, fn) {
    const wrapper = (...args) => {
      this.off(event, wrapper);
      fn(...args);
    };
    return this.on(event, wrapper);
  }

  off(event, fn) {
    if (!this._listeners.has(event)) return;
    const listeners = this._listeners.get(event);
    const idx = listeners.indexOf(fn);
    if (idx !== -1) {
      listeners.splice(idx, 1);
    }
  }

  emit(event, ...args) {
    if (!this._listeners.has(event)) return 0;
    const currentListeners = this._listeners.get(event).slice();
    let invokedCount = 0;
    let firstError = null;
    for (const fn of currentListeners) {
      try {
        fn(...args);
        invokedCount++;
      } catch (err) {
        if (!firstError) {
          firstError = err;
        }
      }
    }
    if (firstError) {
      throw firstError;
    }
    return invokedCount;
  }
}

module.exports = Emitter;
