function createStore(reducer, initial) {
  let state = initial;
  const listeners = [];
  let dispatching = false;

  function getState() {
    return state;
  }

  function subscribe(fn) {
    if (typeof fn !== 'function') {
      throw new Error('Expected listener to be a function');
    }
    let subscribed = true;
    listeners.push(fn);
    return function unsubscribe() {
      if (!subscribed) return;
      subscribed = false;
      const index = listeners.indexOf(fn);
      if (index > -1) {
        listeners.splice(index, 1);
      }
    };
  }

  function dispatch(action) {
    if (dispatching) {
      throw new Error('Dispatching inside a reducer is not allowed');
    }
    dispatching = true;
    try {
      state = reducer(state, action);
    } finally {
      dispatching = false;
    }

    // Snapshot the listener list at this point in time
    const snapshot = listeners.slice();

    for (let i = 0; i < snapshot.length; i++) {
      // Check if this listener is still subscribed
      if (listeners.indexOf(snapshot[i]) === -1) {
        continue;
      }
      try {
        snapshot[i]();
      } catch (e) {
        throw e;
      }
    }

    return action;
  }

  return { getState, dispatch, subscribe };
}

module.exports = createStore;
