export class Bus<E extends Record<string, unknown>> {
  private listeners: Map<keyof E, Set<(payload: never) => void>> = new Map();

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    let set = this.listeners.get(k);
    if (!set) {
      set = new Set();
      this.listeners.set(k, set);
    }
    const wrapped = fn as unknown as (payload: never) => void;
    set.add(wrapped);
    return () => {
      set!.delete(wrapped);
    };
  }

  emit<K extends keyof E>(k: K, ...args: [E[K]] | []): void {
    const payload = args.length > 0 ? (args[0] as E[K]) : undefined;
    const set = this.listeners.get(k);
    if (!set) return;
    for (const fn of set) {
      (fn as unknown as (payload: E[K]) => void)(payload as E[K]);
    }
  }
}
