export type DeepAwaited<T> = T extends Promise<infer U>
  ? DeepAwaited<U>
  : T extends readonly unknown[]
    ? { [K in keyof T]: DeepAwaited<T[K]> }
    : T extends object
      ? { [K in keyof T]: DeepAwaited<T[K]> }
      : T;

export async function deepAwait<T>(value: T): Promise<DeepAwaited<T>> {
  if (value === null || value === undefined) {
    return value as DeepAwaited<T>;
  }

  const type = typeof value;

  // Non-promise, non-object primitives pass through unchanged
  if (type !== 'object' && type !== 'function') {
    return value as DeepAwaited<T>;
  }

  // Functions are untouched
  if (type === 'function') {
    return value as DeepAwaited<T>;
  }

  // Handle promises recursively
  if (value instanceof Promise) {
    const resolved = await value;
    return deepAwait(resolved);
  }

  // Handle arrays
  if (Array.isArray(value)) {
    const results: unknown[] = [];
    for (const item of value) {
      results.push(await deepAwait(item));
    }
    return results as DeepAwaited<T>;
  }

  // Handle plain objects
  const result: Record<string, unknown> = {};
  for (const key of Object.keys(value)) {
    result[key] = await deepAwait((value as Record<string, unknown>)[key]);
  }
  return result as DeepAwaited<T>;
}
