type Tail<A extends unknown[]> = A extends [unknown, ...infer Rest] ? Rest : never;

export function curry<A extends unknown[], R>(fn: (...args: A) => R): Curry<A, R> {
  const curried = (acc: unknown[]): ((...args: unknown[]) => unknown) | R => {
    if (acc.length >= fn.length) {
      return fn(...(acc as A));
    }
    return (...args: unknown[]) => curried([...acc, ...args]);
  };

  const result = curried([]);
  return result as Curry<A, R>;
