type PickKeys<T, K extends keyof T> = {
  readonly [P in K]: T[P];
};

type OmitKeys<T, K extends keyof T> = {
  readonly [P in Exclude<keyof T, K> as P extends keyof T ? (T[P] extends undefined ? never : P) : never]: T[P];
};

export function pick<T, const K extends keyof T>(obj: T, keys: readonly K[]): PickKeys<T, K> {
  const result = {} as Record<string, unknown>;
  for (const key of keys) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      result[key] = obj[key];
    }
  }
  return result as PickKeys<T, K>;
}

export function omit<T, const K extends keyof T>(obj: T, keys: readonly K[]): OmitKeys<T, K> {
  const result = {} as Record<string, unknown>;
  for (const key of Object.keys(obj)) {
    if (!keys.includes(key as K) && Object.prototype.hasOwnProperty.call(obj, key)) {
      result[key] = obj[key];
    }
  }
  return result as OmitKeys<T, K>;
}
