type ParamsOf<P extends string> = P extends `:${infer Name}/${infer Rest}`
  ? { [K in Name | keyof ParamsOf<Rest>]: string }
  : P extends `:${infer Name}`
    ? { [K in Name]: string }
    : {};

type RouteFn<P extends string> = [keyof ParamsOf<P>] extends [never]
  ? () => P
  : (params: ParamsOf<P>) => P;

export function defineRoutes<R extends Record<string, string>>(routes: R): {
  [K in keyof R]: RouteFn<R[K]>;
} {
  const result = {} as any;
  for (const key of Object.keys(routes)) {
    const path = routes[key];
    result[key] = (...args: unknown[]) => {
      if (args.length === 0) return path;
      const params = args[0] as Record<string, string>;
      let out = "";
      let i = 0;
      while (i < path.length) {
        if (path[i] === ":") {
          let j = i + 1;
          while (j < path.length && /[a-zA-Z0-9_]/.test(path[j])) j++;
          const name = path.slice(i + 1, j);
          out += params[name];
          i = j;
        } else {
          out += path[i];
          i++;
        }
      }
      return out;
    };
  }
  return result;
}
