export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (patch === undefined) return base;
  if (Array.isArray(base)) {
    return Array.isArray(patch) ? (patch as unknown as T) : base;
  }
  if (typeof base !== 'object' || base === null) {
    return patch === undefined ? base : (patch as unknown as T);
  }
  const result: Record<string, unknown> = {};
  for (const key of Object.keys(base)) {
    result[key] = (base as Record<string, unknown>)[key];
